+                DataTypes.BOOLEAN,
+                equalTo(str.endsWith(suffix))
+            );
+        }));
+        suppliers.add(new TestCaseSupplier("ends_with randomized test", () -> {
+            String str = randomRealisticUnicodeOfLength(5);
+            String suffix = randomRealisticUnicodeOfLength(5);
