+                        return clusterStateBarriers.computeIfAbsent(clusterStateVersion, ignored -> new SubscribableListener<>());
+                    } finally {
+                        refCounted.decRef();
+                    }
+                } else {
+                    return SubscribableListener.newSucceeded(null);
+                }
+            }
