+                        throw e;
+                    }
+                }
+            }
+            initClient();
+        }
+    }
+
+    @AfterClass
+    public static void resetNodes() {
+        oldIndexVersion = null;
+        upgradedNodes.clear();
+        upgradeFailed = false;
+    }
